  nameTagNoPrefix: [
    'workspace "T" "A test" {',
    '    model {',
    '        a = softwareSystem "A" <X>',
    '    }',
    '}',
  ].join("\n"),
  nameDescTwoTagsNoPrefix: [
    'workspace "T" "A test" {',
    '    model {',
