    '    }',
    '}',
  ].join("\n"),
  personWithTag: [
    'workspace "T" "A test" {',
    '    model {',
    '        p = person "P" "desc" <X>',
    '    }',
    '}',
  ].join("\n"),
  containerWithTag: [
    'workspace "T" "A test" {',
    '    model {',
    '        s = softwareSystem "S" {',
    '            c = container "C" "desc" "Tech" <X>',
    '        }',
    '    }',
    '}',
  ].join("\n"),
};
const out = {};
for (const [k, dsl] of Object.entries(tests)) {
  const r = await tools.structurizr.parse({ dsl });
  if (typeof r === "string") { out[k] = r; }
