    // extract just the relevant element's tags/description
    const ss = r.model?.softwareSystems || [];
    out[k] = ss.map(x => ({ name: x.name, description: x.description, tags: x.tags, containers: (x.containers||[]).map(c=>({name:c.name,description:c.description,tags:c.tags})) }));
  }
}
return out;

